#include <iostream>
#include <vector>
#include <cmath>

using namespace std;

class Vector {
public:
    int components[5];

    Vector(const int a[], const int b[]) {
        for (int i = 0; i < 5; i++) {
            components[i] = b[i] - a[i];
        }
    }

    double mag() const {
        double sumSquares = 0;
        for (int c : components) {
            sumSquares += c * c;
        }
        return sqrt(sumSquares);
    }

    int prod(const Vector& v) const {
        int sum = 0;
        for (int i = 0; i < 5; i++) {
            sum += components[i] * v.components[i];
        }
        return sum;
    }
};

